export interface Issue {
  /** The field the issue is about. */
  path: string
  message: string
}

export type CheckResult<T> = { ok: true; value: T } | { ok: false; issues: Issue[] }

export interface StringRule {
  /** At least `length` characters. */
  min(length: number, message?: string): StringRule
  /** Something that looks like an email address: text, an @, then more text. */
  email(message?: string): StringRule
}

export interface Schema<T> {
  /** Every rule of every field; issues come in the order of the fields. */
  check(value: unknown): CheckResult<T>
}

export function string(): StringRule
export function schema<T extends Record<string, unknown>>(shape: Record<keyof T, StringRule>): Schema<T>
